<?php
namespace qqworld_collector\module\collecting\method; use qqworld_collector\lib; class regex extends lib { var $guid = 'regex'; public function __construct() { add_filter( 'qqworld-collector-collecting-method-' . $this->guid, array($this, 'parse'), 10, 3); } public function parse_regex_pattern($pattern) { $patterns = array( '/\\\\\(\\\!(.*?)\\\!\\\\\\)/i', '/\\\\\(\\\!(.*?)\\\!:\\\\\\*\\\\\\)/i', '/\\\\\(content:\\\!(.*?)\\\!\\\\\\)/i', '/\\\\\(content:\\\!(.*?)\\\!:\\\\\\*\\\\\\)/i' ); $replacements = array( '[^${1}]*?', '[^${1}]*', '([^${1}]*?)', '([^${1}]*)' ); $pattern = preg_replace($patterns, $replacements, $pattern); $preg = preg_match('/\\\\\(o:([^\)]*)\\\\\)/', $pattern, $match); if ($preg) { $pattern = str_replace($match[0], '['.str_replace('\|', '|', $match[1]).']', $pattern); } $patterns = array( '\(\^\)', '\(\$\)', '\(\*\)', '\(\*:\*\)', '\(d\)', '\(d:\*\)', '\(n\)', '\(n:\*\)', '\(w\)', '\(w:\*\)', '\(\.\)', '\(\.:\*\)', '\(c\)', '\(c:\*\)', '\(content\)', '\(content:\*\)', '\(content:d\)', '\(content:d:\*\)', '\(content:w\)', '\(content:w:\*\)', '\(content:\.\)', '\(content:\.:\*\)', '\(content:c\)', '\(content:c:\*\)', ); $replacements = array( '^', '$', '[\s\S]*?', '[\s\S]*', '\d*?', '\d*', '[\n\r\s\t]*?', '[\n\r\s\t]*', '\w*?', '\w*', '.*?', '.*', '[\u4e00-\u9fa5]*?', '[\u4e00-\u9fa5]*', '([\s\S]*?)', '([\s\S]*)', '(\d*?)', '(\d*)', '(\w*?)', '(\w*)', '(.*?)', '(.*)', '([\u4e00-\u9fa5]*?)', '([\u4e00-\u9fa5]*)', ); $pattern = str_replace($patterns, $replacements, $pattern); if (preg_match('/\\\{(var:.*)\\\}/i',$pattern)) { $pattern = preg_replace('/\\\{(var:.*)\\\}/i', '{$1}', $pattern); $pattern = apply_filters( 'qqworld-collector-collection-project-variable-filter', $pattern, 0 ); } return $pattern; } public function parse($html, $value, $index) { $results = false; $value = explode("\r\n", $value); foreach ($value as $val) { $val = trim($val); $pattern = $this->encode_pattern($val); $pattern = $this->parse_regex_pattern($pattern); $preg = preg_match_all('/'.$pattern.'/i', $html, $matches); if (!$preg) { $html = stripcslashes($html); $preg = preg_match_all('/'.$pattern.'/i', $html, $matches); } if ($preg) { if ($results === false) $results = array(); $result = isset($matches[1]) ? $matches[1] : $matches[0]; if ($index == -1) { $result = array($result[count($result)-1]); } elseif ($index != 'all') { if (isset($result[$index])) $result = array($result[$index]); else $result = ''; } if (is_array($result)) $results = array_merge($results, $result); else $results[] = $result; } } return $results; } } ?>